import json,os,subprocess as s,sys,tempfile
def fail(m):
    print(m);sys.exit(1)
def snap(free,orphan):
    procs=[{'pid':4242,'age_s':9,'class':'orphan' if orphan else 'hook','checkout':'.','session':None,'item':None}]
    host={'load':[1.0,1.0,1.0],'cores':8,'suite_lock':None,'main_lock':None,'ceiling':{'error':'planted'},'disk':{'free_bytes':free*10**9,'total_bytes':100*10**9,'free_pct':free}}
    d={'schema':1,'taken':'2026-10-19T00:00:00Z','alerts':[],'panels':{'sessions':{'state':'ok','seconds':0.1,'data':{'procs':procs,'worktrees':[]}},'host':{'state':'ok','seconds':0.1,'data':host}}}
    f=os.path.join(tempfile.mkdtemp(),'s.json');json.dump(d,open(f,'w'));return f
def judged(f):
    p=s.run([sys.executable,'_tools/kbmon.py','--json','--from-snapshot',f],capture_output=True,text=True,timeout=120)
    if p.returncode not in (0,1): fail('exit %s: %s'%(p.returncode,p.stderr[-300:]))
    return {(a['kind'],a['id']) for a in json.loads(p.stdout)['alerts']},p.returncode
k,rc=judged(snap(3,True))
if ('orphan','sessions.orphan') not in k or ('disk','host.disk') not in k or rc!=1: fail('alerts %r exit %s'%(sorted(k),rc))
k,rc=judged(snap(60,False))
if any(x[0] in ('orphan','disk') for x in k): fail('alerts on a healthy snapshot: %r'%sorted(k))
print('ok: an orphan and 3% free disk are alerts; a healthy snapshot has neither')
